-- Bring the PostgreSQL initial published representation in line with the existing
-- Announcement page design. Existing authored versions are never overwritten.
INSERT INTO content_versions (document_id, version_number, state, payload, authored_by, authored_provider, published_by, published_at, change_summary)
SELECT 1,
       (SELECT COALESCE(MAX(version_number), 0) + 1 FROM content_versions WHERE document_id = 1),
       'published',
       $$ {"schemaVersion":1,"hero":{"title":"Announcements","body":"Please stay updated with the latest changes and announcements to ensure the best experience while using the application."},"carousel":[{"id":"bayona","name":"Mark Anthony Bayona","image":"assets/images/congrats1.png","body":"Certified Full Stack Developer","order":0},{"id":"ignacio","name":"Alison Ignacio","image":"assets/images/congrats2.png","body":"Certified Full Stack Developer","order":1},{"id":"ardione","name":"Ardione David","image":"assets/images/congrats3.png","body":"Certified Full Stack Developer","order":2},{"id":"fernandez","name":"Henry Fernandez","image":"assets/images/congrats4.png","body":"Certified Full Stack Developer","order":3}],"trainings":[{"id":"tq","title":"Technology Quotient (TQ)","description":"New technologies are helping our clients reinvent their businesses. Stay relevant and complete foundational courses on new technologies.","link":"https://www.pluralsight.com","linkLabel":"Pluralsight","order":0},{"id":"gen-ai","title":"Gen AI Trainings","description":"Learn more and use this cutting-edge technology to help Accenture and our clients maximize the value of Gen AI.","link":"https://in.accenture.com/philippines/","linkLabel":"Buhay Accenture","order":1},{"id":"workday","title":"Workday: Required Trainings","description":"Visit Learning Home in Workday and find required trainings.","link":"https://wd103.myworkday.com/accenture/learning","linkLabel":"Workday","order":2},{"id":"mha","title":"Global Mental Health Ally Training","description":"The Mental Health Ally program equips people to foster a supportive, inclusive workplace.","link":"https://wd103.myworkday.com/accenture/learning","linkLabel":"Workday","order":3},{"id":"isa","title":"IS Gold Advocate","description":"Stay up to date with your IS Advocate training and recommended actions.","link":"https://in.accenture.com/protectingaccenture/dashboard/","linkLabel":"ISA Dashboard","order":4},{"id":"coding","title":"Coding Standards","description":"Learn the rules and principles that support good code and good practices.","link":"https://in.accenture.com/cioorganization/cio-bootcamp/cio-bootcamp-roles/developer/coding-standards/","linkLabel":"CIO Organization","order":5}],"notices":[{"id":"carousel","title":"New feature: Carousel","body":"Certificate Gallery has been added to make your experience more interactive and engaging.","order":0}],"reminder":{"title":"Reminder","body":"Do not forget to check your latest updates and complete pending tasks to stay up to date with the system."}} $$::jsonb,
       'migration', 'system', 'migration', NOW(), 'Announcement seed parity'
WHERE NOT EXISTS (
  SELECT 1 FROM content_versions WHERE document_id = 1 AND jsonb_array_length(payload->'carousel') > 0
);

UPDATE content_documents
SET published_version_id = (SELECT id FROM content_versions WHERE document_id = 1 AND jsonb_array_length(payload->'carousel') > 0 ORDER BY version_number DESC LIMIT 1), updated_at = NOW()
WHERE id = 1 AND jsonb_array_length((SELECT payload FROM content_versions WHERE id = content_documents.published_version_id)->'carousel') = 0;
